Lemma in_sidesB_of_hull : forall bc D kb obr glo ghi kk mm,
  existsb (hull_in_side kb obr glo ghi) D = true ->
  base_rangeB bc kb = obr -> (glo <= kk)%Z -> (kk + mm <= ghi)%Z -> (0 <= mm < two64)%Z ->
